static void manifest(QrxAuraModelCatalogAnnouncement*c){memset(c,0,sizeof(*c));c->version=1;snprintf(c->publisher_id,sizeof(c->publisher_id),"gov");c->sequence=1;c->valid_from_height=1;c->valid_until_height=1000;c->popularity_bps=7000;c->priority_bps=8000;QrxAuraModelManifest*m=&c->manifest;m->version=1;snprintf(m->model_id,sizeof(m->model_id),"qrx:model:synthetic:moe");snprintf(m->model_version,sizeof(m->model_version),"1");snprintf(m->family,sizeof(m->family),"synthetic");snprintf(m->architecture,sizeof(m->architecture),"moe");snprintf(m->format,sizeof(m->format),"gguf");snprintf(m->quantization,sizeof(m->quantization),"q4");snprintf(m->license_id,sizeof(m->license_id),"test");m->max_context_tokens=8192;m->asset_count=4;for(uint32_t i=0;i<4;i++){m->assets[i].index=i;m->assets[i].bytes=(i+1)*1024*1024;hx(m->assets[i].content_root,(char)('a'+i));m->total_bytes+=m->assets[i].bytes;}m->assets[0].kind=QRX_AURA_ASSET_CONFIG;m->assets[0].required_for_boot=1;m->assets[1].kind=QRX_AURA_ASSET_SHARED_WEIGHTS;m->assets[1].required_for_boot=1;m->assets[2].kind=QRX_AURA_ASSET_EXPERT_PACK;m->assets[2].expert_first=0;m->assets[2].expert_count=8;m->assets[3].kind=QRX_AURA_ASSET_EXPERT_PACK;m->assets[3].expert_first=8;m->assets[3].expert_count=8;(void)qrx_aura_model_manifest_commitment(m,c->manifest_root);}
