int main(void){QrxAuraModelCatalogAnnouncement c;manifest(&c);QrxAuraModelProviderIndex*idx=calloc(1,sizeof(*idx));CHECK(idx);qrx_aura_model_provider_index_init(idx);ad(idx,&c,"p1","pod1","DE",2,0x0f);ad(idx,&c,"p2","pod2","NL",10,0x07);ad(idx,&c,"p3","pod3","US",70,0x03);QrxAuraPlacementCandidate cand[3];candidate(&cand[0],"target-de","tde","DE",2000,3);candidate(&cand[1],"target-fr","tfr","FR",2500,15);candidate(&cand[2],"target-jp","tjp","JP",8000,150);QrxAuraModelDemandStat dem[2]={{2,5000,1000,15},{3,9500,9000,60}};QrxAuraReplicationRepairPlan p;CHECK(qrx_aura_model_repair_plan(&c,idx,100,cand,3,dem,2,&p)==0);CHECK(p.item_count>=2&&p.transfer_bytes>0);int saw3=0,saw_region=0;for(uint32_t i=0;i<p.item_count;i++){if(p.items[i].asset_index==3){saw3=1;CHECK(p.items[i].reason==QRX_AURA_REPAIR_HOT_EXPERT);CHECK(!strcmp(p.items[i].target_region,"FR"));}if(p.items[i].reason==QRX_AURA_REPAIR_REGION_GAP)saw_region=1;}CHECK(saw3&&saw_region);CHECK(p.items[0].priority_score>=p.items[p.item_count-1].priority_score);qrx_aura_model_provider_index_free(idx);free(idx);printf("phase168 AURA autoplacement/repair/hot expert: PASS\n");return 0;}
